import dotenv from "dotenv";
import path from "path";
import { fileURLToPath } from "url";
const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
dotenv.config({ path: path.join(__dirname, "../.env") });
import Groq from "groq-sdk";

const groq = new Groq({ apiKey: process.env.GROQ_API_KEY });

async function main() {
  console.log("🚀 Testing Llama 3.2 Vision Preview...");
  try {
    const completion = await groq.chat.completions.create({
      model: "llama-3.2-11b-vision-instruct", // Trying instruct version
      messages: [
        {
          role: "user",
          content: [
            { type: "text", text: "What is this?" },
            {
              type: "image_url",
              image_url: {
                url: "data:image/jpeg;base64,",
              },
            },
          ],
        },
      ],
    });
    console.log(
      "✅ Model responded:",
      completion.choices[0]?.message?.content?.slice(0, 100) + "...",
    );
  } catch (err) {
    console.error("❌ Vision Test Failed:", err.message);
    if (err.error) console.error(JSON.stringify(err.error, null, 2));
  }
}

main().catch(console.error);
